import java.io.*;
import java.util.*;

public class sd {
    public static long max(long num, long num2) {
        return 1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split("\\s+");
        int w = Integer.parseInt(input[0]);
        int m = Integer.parseInt(input[1]);
        br.close();

        boolean valid = true;
        int[] representation = new int[40];
        int pos = 0;

        while (m > 0) {
            representation[pos++] = m % w;
            m /= w;
        }

        for (int i = 0; i <= pos; i++) {
            int digit = representation[i];
            if (digit != 0 && digit != 1 && digit != w && digit != w - 1) {
                valid = false;
                break;
            }
            if (digit == w || digit == w - 1) {
                representation[i + 1]++;
            }
        }

        System.out.println(valid ? "YES" : "NO");
    }
}
